"""SentinelX reports: JSON export + self-contained dark HTML report."""

from __future__ import annotations

import json
import time
from pathlib import Path

from sentinelx.core.models import Finding, esc, SEVERITY_ORDER

DISCLAIMER = (
    "Legal notice: this report was generated by an automated scanner against a target "
    "the operator confirmed they own or are authorized to test. Findings are point-in-time "
    "observations; verify each manually before acting. Do not use this tool against systems "
    "you do not own or lack explicit written permission to test."
)


def write_json(findings: list[Finding], path: str, meta: dict | None = None):
    data = {
        "tool": "SentinelX 1.0.0",
        "generated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "meta": meta or {},
        "disclaimer": DISCLAIMER,
        "findings": [f.to_dict() for f in findings],
    }
    Path(path).write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")


def write_html(findings: list[Finding], path: str, target: str):
    ordered = sorted(findings, key=lambda f: SEVERITY_ORDER.get(f.severity, 0), reverse=True)
    counts = {}
    for f in ordered:
        counts[f.severity] = counts.get(f.severity, 0) + 1
    sev_color = {"critical": "#f43f5e", "high": "#fb923c", "medium": "#facc15",
                 "low": "#38bdf8", "info": "#94a3b8"}

    cards = []
    for f in ordered:
        c = sev_color.get(f.severity, "#94a3b8")
        cards.append(f"""
        <article class="card">
          <div class="card-head">
            <span class="sev" style="background:{c}">{esc(f.severity.upper())}</span>
            <div><h3>{esc(f.type)} <span class="sub">{esc(f.subtype)}</span></h3>
            <div class="meta">{esc(f.method)} {esc(f.url)} · param <code>{esc(f.param)}</code> · CVSS {f.cvss_score} · confidence {f.confidence:.0%}</div></div>
          </div>
          <div class="grid">
            <div><h4>Payload</h4><pre class="code">{esc(f.payload)}</pre>
            <h4>Proof</h4><p>{esc(f.evidence.proof)}</p>
            <h4>Reproduce</h4><pre class="code curl">{esc(f.curl_command)}</pre>
            <button onclick="navigator.clipboard.writeText(this.previousElementSibling.innerText)">Copy curl</button></div>
            <div><h4>Request (raw)</h4><pre class="code">{esc(f.evidence.request_raw)}</pre>
            <h4>Response (raw)</h4><pre class="code">{esc(f.evidence.response_raw)}</pre></div>
          </div>
          <div class="foot"><span><b>CWE:</b> {esc(f.cwe)}</span><span><b>OWASP:</b> {esc(f.owasp)}</span>
          <span><b>CVSS vector:</b> <code>{esc(f.cvss_vector)}</code></span></div>
          <h4>Remediation</h4><p>{esc(f.remediation)}</p>
        </article>""")

    summary = " ".join(
        f'<span class="pill" style="border-color:{sev_color.get(s, "#94a3b8")}">{s}: {n}</span>'
        for s, n in sorted(counts.items(), key=lambda x: SEVERITY_ORDER.get(x[0], 0), reverse=True)
    ) or '<span class="pill">No findings</span>'

    html_doc = f"""<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>SentinelX report — {esc(target)}</title>
<style>
:root{{color-scheme:dark}}
*{{box-sizing:border-box}}body{{margin:0;background:#0b0f16;color:#e6edf3;font-family:system-ui,sans-serif}}
.wrap{{max-width:1100px;margin:0 auto;padding:24px}}
header{{padding:28px 0;border-bottom:1px solid #1f2a3a}}
h1{{margin:0 0 6px}}h3{{margin:0}}h4{{margin:14px 0 6px;color:#9fb3c8;font-size:13px;text-transform:uppercase;letter-spacing:.06em}}
.pill{{display:inline-block;border:1px solid #334155;border-radius:999px;padding:4px 12px;margin:2px;font-size:13px}}
.card{{background:#111827;border:1px solid #1f2a3a;border-radius:14px;padding:18px;margin:16px 0}}
.card-head{{display:flex;gap:12px;align-items:flex-start}}
.sev{{color:#0b0f16;font-weight:800;font-size:11px;padding:4px 10px;border-radius:8px;white-space:nowrap}}
.sub{{color:#9fb3c8;font-weight:400;font-size:14px}}
.meta{{color:#9fb3c8;font-size:12.5px;margin-top:4px;word-break:break-all}}
.grid{{display:grid;grid-template-columns:1fr 1fr;gap:16px}}
@media(max-width:760px){{.grid{{grid-template-columns:1fr}}}}
.code{{background:#0a0e14;border:1px solid #1f2a3a;border-radius:8px;padding:10px;overflow:auto;font-size:12px;white-space:pre-wrap;word-break:break-all;max-height:320px}}
button{{background:#1f6feb;border:none;color:#fff;border-radius:8px;padding:8px 14px;cursor:pointer;font-size:13px}}
.foot{{display:flex;gap:16px;flex-wrap:wrap;color:#9fb3c8;font-size:12.5px;margin-top:10px}}
footer{{color:#64748b;font-size:12px;padding:24px 0}}
p{{line-height:1.6}}
</style></head>
<body><div class="wrap">
<header><h1>🛡 SentinelX scan report</h1>
<div>Target: <code>{esc(target)}</code> · {time.strftime("%Y-%m-%d %H:%M UTC", time.gmtime())} · {len(ordered)} findings</div>
<div style="margin-top:10px">{summary}</div></header>
{''.join(cards) or '<p>No findings. The target resisted all tested vectors.</p>'}
<footer>{esc(DISCLAIMER)}</footer>
</div></body></html>"""
    Path(path).write_text(html_doc, encoding="utf-8")
